"""Generates the data-driven documents in docs/ from the repository and from the training outputs, so that every number in them comes from a file.

    python3 tools/clrs_docs_generate.py --models <folder with <algo>.json model manifests> \
                                        --reports <clrs-transcoder-out> --results <results_v3>

Writes docs/04-the-12-algorithms.md, docs/15-latent-dictionaries.md, docs/16-transcoder-training-reports.md, docs/17-fig47-study-results.md and
docs/06b-hover-text-catalog.md. (The other documents in docs/ are written by hand.) Needs only numpy-free Python 3 and Node (to read pseudo_block.js and explain.js).
"""
import argparse, json, os, subprocess, textwrap

ap = argparse.ArgumentParser()
ap.add_argument('--models', required=True); ap.add_argument('--reports', required=True); ap.add_argument('--results', required=True)
ap.add_argument('--repo', default='.'); A = ap.parse_args()
R = A.repo; DOCS = os.path.join(R, 'docs'); os.makedirs(DOCS, exist_ok=True)
ALGOS = ['bfs', 'dfs', 'bellman_ford', 'dijkstra', 'dag_shortest_paths', 'mst_prim', 'mst_kruskal', 'topological_sort', 'articulation_points', 'bridges', 'strongly_connected_components', 'floyd_warshall']
J = lambda *p: json.load(open(os.path.join(*p)))
summary = J(A.results, 'summary_v3.json'); SUM = {r['algo']: r for r in summary['results']}
edge_sum = J(R, 'edge_tc', 'clrs-edge-summary.json')['summary']
meta = {a: J(R, 'algos', a, 'meta.json') for a in ALGOS}; flab = {a: J(R, 'algos', a, 'feature_labels.json') for a in ALGOS}
rep = {a: J(A.reports, a, 'report.json') for a in ALGOS}; lat = {a: J(R, 'edge_tc', a + '.latents.json') for a in ALGOS}
man = {a: J(A.models, a + '.json') for a in ALGOS}
code = json.loads(subprocess.run(['node', '-e', "console.log(JSON.stringify(require(process.argv[1]).CODE))", os.path.abspath(os.path.join(R, 'verification/pseudo/pseudo_block.js'))], capture_output=True, text=True, check=True).stdout)
tips = json.loads(subprocess.run(['node', os.path.abspath(os.path.join(R, 'tools/clrs_dump_tips.js')), os.path.abspath(os.path.join(R, 'explain.js'))], capture_output=True, text=True, check=True).stdout)
pct = lambda x, d=1: 'n/a' if x is None else f'{x * 100:.{d}f}%'
f4 = lambda x: 'n/a' if x is None else f'{x:.4f}'
GEN = '> This file is generated by `tools/clrs_docs_generate.py` from the repository and the training outputs; do not edit it by hand. Re-run the generator after any change to the data.\n'

# ---------------------------------------------------------------------------------------------------------------------------------------------
# what each algorithm is (hand-written, textbook level)
# ---------------------------------------------------------------------------------------------------------------------------------------------
ALG = {
 'bfs': ('Breadth-first search', ['Starting from a source node s, BFS visits the graph in rings: first s, then every node one edge away, then every node two edges away, and so on.',
   'The result is a tree of parent pointers (pi): every reached node points to the node it was first reached from.', 'It runs in O(V + E) time on an adjacency list.'],
   'The model has to learn a simple rule: "a node becomes reached when some already-reached node has an edge to it". Each message-passing step it executes one ring of the search.',
   'The easiest of the twelve: the model keeps 99.8% accuracy on graphs four times bigger than it was trained on.'),
 'dfs': ('Depth-first search', ['DFS explores as deep as possible along each path before backing up. It colours nodes white (not seen), gray (being explored) and black (finished) and records discovery and finishing times.',
   'The order in which nodes are finished is the basis of topological sorting and of strongly connected components.', 'It runs in O(V + E) time.'],
   'The model has to keep an implicit stack: which node is currently being explored and which neighbours are still unvisited. The target the site explains is the colour of each node.',
   'Perfect on the training size, but the stack depth seems tied to 16 nodes: on 64-node graphs it keeps only 48% (SEVERE).'),
 'bellman_ford': ('Bellman-Ford shortest paths', ['Computes the shortest distance from a source to every node, even when edge weights are negative. It repeats "relax every edge" |V| - 1 times: if going through edge (u, v) gives a shorter path to v, update d[v] and the parent pointer.',
   'It runs in O(V * E) time.'], 'Each message-passing step is one round of relaxation over all edges, which is exactly what a max-aggregating message-passing layer can express. The site explains the distance d.',
   'Generalises well (94.8% on 64 nodes, CLEAN).'),
 'dijkstra': ('Dijkstra shortest paths', ['Computes shortest distances from a source when all weights are non-negative. It keeps a priority queue of unfinished nodes, repeatedly extracts the closest one, marks it finished and relaxes its outgoing edges.',
   'It runs in O((V + E) log V) with a binary heap.'], 'The model has to find the closest unfinished node each step (an arg-min over nodes) and update its neighbours. The site explains the distance d.',
   'CLEAN: 97.7% on 64 nodes. One of the two algorithms (with Prim) where the transcoder-in-the-network agreement is lowest on this site.'),
 'dag_shortest_paths': ('Shortest paths in a directed acyclic graph', ['First sort the nodes topologically, then visit them in that order and relax each node\'s outgoing edges once. Because every node is visited after all its predecessors, one pass is enough.',
   'It runs in O(V + E) time.'], 'The model has to follow a topological order it was never given explicitly (it is computed as hints) and relax edges once. The site explains the distance d.', 'CLEAN: 98.4% on 64 nodes.'),
 'mst_prim': ('Prim minimum spanning tree', ['Grows one tree from a start node: repeatedly add the cheapest edge that connects a node in the tree to a node outside it. The result is a minimum-weight tree that touches every node.',
   'It runs in O((V + E) log V) with a binary heap.'], 'The model keeps, for every node outside the tree, the weight of its cheapest connection (key) and has to pick the smallest each step. The site explains the key.', 'CLEAN: 92.6% on 64 nodes.'),
 'mst_kruskal': ('Kruskal minimum spanning tree', ['Sorts all edges by weight and adds them one by one unless they would close a cycle. A union-find structure answers "are these two nodes already connected?".',
   'It runs in O(E log E).'], 'The model has to sort edges implicitly and run union-find, which is hard for a message-passing network. The site explains the mask that marks the edge currently considered.',
   'SEVERE and also the weakest on its own training size (90.5% validation): tier C.'),
 'topological_sort': ('Topological sort', ['Orders the nodes of a directed acyclic graph so that every edge points forwards. The textbook way is to run DFS and list nodes in decreasing finishing time.', 'It runs in O(V + E).'],
   'The model has to run a DFS-like process and emit the nodes in order. The site explains the head of the list (the node that has just been placed).', 'SEVERE: 51.7% on 64 nodes.'),
 'articulation_points': ('Articulation points (cut vertices)', ['A cut vertex is a node whose removal disconnects the graph. It is found with one DFS that tracks, for each node, the lowest discovery time reachable from its subtree ("low").',
   'The root is a cut vertex if it has two or more DFS children; any other node u is one if some child v has low[v] >= d[u].', 'It runs in O(V + E).'],
   'The model has to simulate DFS and the low-link bookkeeping. The site explains the "is a cut vertex" mask.', 'CLEAN: 94.9% on 64 nodes.'),
 'bridges': ('Bridges', ['A bridge is an edge whose removal disconnects the graph. It is found with the same DFS and low-link bookkeeping as articulation points: the tree edge (u, v) is a bridge if low[v] > d[u].', 'It runs in O(V + E).'],
   'Same machinery as articulation points. The site explains the DFS colour of each node (the hint that drives the search).', 'CLEAN: 96.8% on 64 nodes.'),
 'strongly_connected_components': ('Strongly connected components', ['Two nodes are in the same strongly connected component if each can reach the other. The classical algorithm runs DFS, reverses all edges, and runs DFS again in decreasing finishing time; every tree of the second search is one component.',
   'It runs in O(V + E).'], 'The model has to run two DFS passes with a graph reversal in between. The site explains the DFS colour of each node.', 'SEVERE and the largest gap of all: 27.3% on 64 nodes.'),
 'floyd_warshall': ('Floyd-Warshall all-pairs shortest paths', ['Computes the shortest distance between every pair of nodes. For each intermediate node k in turn, it checks whether going i -> k -> j beats the best known i -> j.',
   'It runs in O(V^3) time; the three nested loops are k (outer), i and j.'], 'The model keeps an N x N table of distances and has to apply the k-th relaxation to all pairs at once. The site explains the mask that marks the current k.',
   'SEVERE and tier C: only 93.1% validation and 38.5% on 64 nodes.'),
}

# ---------------------------------------------------------------------------------------------------------------------------------------------
# 04 the 12 algorithms
# ---------------------------------------------------------------------------------------------------------------------------------------------
fig = J(R, 'fig47', 'phase2agg_summary.json'); ph0 = J(R, 'fig47', 'phase0_results.json'); mch = J(R, 'fig47', 'phase3_maskchanged_summary.json')
def algos_doc():
    L = ['# The 12 algorithms, one by one', '', GEN, '',
         'Each section lists, for one algorithm: what it computes; the CLRS fields the network reads (inputs and hints); the target the site explains; the pseudo-code the site shows; how well the MPNN was trained; how well the new edge-site transcoder reproduces it; the old node-site transcoder (kept at `/demo`); what the new latents turn out to mean; and what the earlier Figure 4 / Figure 7 study found.', '',
         'Terminology used in the tables is explained in `02-glossary.md`. "pp" means percentage points.', '']
    L += ['## Contents', ''] + [f'{i + 1}. [{ALG[a][0]} (`{a}`)](#{a.replace("_", "-")})' for i, a in enumerate(ALGOS)] + ['']
    L += ['## All twelve at a glance', '', '| algorithm | target explained | target type | MPNN val F1 | MPNN test F1 (64 nodes) | gap | class | tier | edge-site retention (val) | edge-site FVU (val) | latents that fire | latents named |', '|---|---|---|---|---|---|---|---|---|---|---|---|']
    for a in ALGOS:
        s = SUM[a]; gap = s['best_val_f1'] - s['test_f1']; e = edge_sum[a]
        L.append(f"| `{a}` | `{meta[a]['target']}` | {meta[a]['target_type']} | {pct(s['best_val_f1'])} | {pct(s['test_f1'])} | {gap * 100:.1f} pp | {'CLEAN' if gap < 0.10 else 'SEVERE' if gap > 0.40 else 'in between'} | {e['tier']} | {pct(e['retention_val'])} | {f4(e['nmse_val'])} | {lat[a]['fired']} | {lat[a]['named']} |")
    L += ['']
    for a in ALGOS:
        s = SUM[a]; e = edge_sum[a]; r = rep[a]; m = meta[a]; lt = lat[a]; title, what, learns, note = ALG[a]; gap = s['best_val_f1'] - s['test_f1']
        L += [f'## {title} (`{a}`)', '', '### What it computes', ''] + what + ['', '### What the network has to learn', '', learns, '', f'In one line: {note}', '']
        L += ['### The CLRS fields the network reads', '', 'The model bundle (`models/<algo>.json`, written by `model_export.py`) lists every input and hint field with its location and type. Output-stage fields are not exported because the browser only needs the hints.', '',
              '| field | stage | location | type | width (K) | meaning of the columns |', '|---|---|---|---|---|---|']
        for f in man[a]['fields']:
            L.append(f"| `{f['name']}` | {f['stage']} | {f['loc']} | {f['type']} | {f.get('K', '')} | {'node = one value per node; edge = one per ordered pair; graph = one for the whole graph' if f is man[a]['fields'][0] else ''} |")
        L += ['', f"Counting both stages, the network encodes {sum(1 for f in man[a]['fields'])} fields; the processor weights, the encoders and the hint decoders together make {man[a]['nfloats']:,} float32 numbers ({man[a]['nfloats'] * 4 / 1e6:.2f} MB), which is the size of `models/{a}.bin`.", '']
        L += ['### The target the site explains', '', f"- target hint: `{m['target']}` ({m['target_type']}), stage `{m['target_stage']}`", f"- source field: `{m['source_field']}`" if m['source_field'] else '- this algorithm has no source node',
              {'mask': '- a mask holds one true/false value per node; many nodes can be true at once.', 'mask_one': '- a mask_one holds exactly one true node per step (a softmax over nodes).',
               'categorical': '- a categorical target holds one class per node (for example a DFS colour).', 'scalar': '- a scalar target holds one real number per node (a distance or a key).'}[m['target_type']], '']
        L += ['### The pseudo-code the site shows', '', 'The line numbers are the ones used by the highlighting. Indentation shows nesting; the colours on the page show the depth of the line.', '', '```text']
        for i, (ind, txt) in enumerate(code[a]):
            L.append(f'{i + 1:>3}  ' + '  ' * ind + txt)
        L += ['```', '']
        L += ['### How well the MPNN was trained', '', '| quantity | value |', '|---|---|', f"| training steps | {s['steps_run']:,} |", f"| training time on the rented GPU | {s['elapsed_min']:.1f} min |", f"| best validation F1 (16-node graphs) | {pct(s['best_val_f1'], 2)} |",
              f"| test F1 on 64-node graphs (never seen) | {pct(s['test_f1'], 2)} |", f"| gap | {gap * 100:.2f} pp |", f"| class | {'CLEAN (gap below 10 pp)' if gap < 0.10 else 'SEVERE (gap above 40 pp)'} |",
              f"| batch size / hidden size / learning rate | {summary['protocol']['batch_size']} / {summary['protocol']['hidden_size']} / {summary['protocol']['learning_rate']} |", f"| hint teacher forcing | {summary['protocol']['hint_teacher_forcing']} |", f"| GPU | {summary['instance']} |", '']
        L += ['### The new edge-site transcoder', '', '| quantity | value |', '|---|---|', f"| latents D / active per pair k | {e['D']} / {e['k']} |", f"| tier | {e['tier']} |", f"| reconstruction error (FVU), train / validation / 64 nodes | {f4(e['nmse_train'])} / {f4(e['nmse_val'])} / {f4(e['nmse_n64']) if e['nmse_n64'] is not None else 'not measured'} |",
              f"| latents that never fire (training rows) | {pct(e['dead_frac_train'])} |", f"| active latents per pair (mean) | {e['l0_val']:.2f} |", f"| replacement keeps (F1), 16 nodes | {pct(e['retention_val'])} ({e['f1_full_val']:.3f} of {e['f1_off_val']:.3f}) |",
              f"| replacement keeps (F1), 64 nodes | {pct(e['retention_n64']) + f' ({e['f1_full_n64']:.3f} of {e['f1_off_n64']:.3f})' if e['retention_n64'] is not None else 'not measured'} |", f"| winner flips when the replacement runs alone | {pct(e['winner_flip_rate'])} of channels |",
              f"| flip bound (2 x error >= gap) violated | {e['winner_flip_violations']} times |", f"| one-step hidden-state error (mean over steps) | {pct(sum(e['hidden_rel_error_direct']) / len(e['hidden_rel_error_direct']))} |", f"| training | {e['train_steps']:,} steps on {e['train_rows']:,} rows, {e['minutes']} min |",
              f"| match with the recorded baseline score (parity) | difference {e['parity_abs_diff']} |", f"| node-site transcoder, replaced alone / both sites (val retention) | {pct(e['node_site_retention_val']) if e['node_site_retention_val'] is not None else '-'} / {pct(e['both_sites_retention_val']) if e['both_sites_retention_val'] is not None else '-'} (not used on the site) |", '']
        L += ['Reconstruction error by algorithm step (validation graphs):', '', '| step | ' + ' | '.join(str(i) for i in range(len(e['nmse_per_step_val']))) + ' |', '|---|' + '---|' * len(e['nmse_per_step_val']), '| FVU | ' + ' | '.join(f'{v:.4f}' for v in e['nmse_per_step_val']) + ' |', '']
        L += ['### The old node-site transcoder (shown at `/demo`)', '', '| quantity | value |', '|---|---|', f"| features F / active k | {m['F']} / {m['K']} |", f"| input | 384 numbers: this node's encoded inputs and previous state (256) plus the max-aggregated incoming message (128) |", f"| reconstruction error (FVU) | {f4(m['fvu'])} |",
              f"| rows used to train and label it | {m['n_rows']:,} |", f"| time to train | {m['elapsed_s']:.0f} s |", '', 'Best-labelled features (precision, recall, F1 of the label against the hint predicate; "fires on" = sites where the feature is among the top k):', '', '| feature | label | P | R | F1 | fires on |', '|---|---|---|---|---|---|']
        for row in flab[a]['rows'][:10]:
            L.append(f"| f{row['feature']} | {row['label']} | {row['precision']:.3f} | {row['recall']:.3f} | {row['f1']:.3f} | {row['n_fire']:,} of {flab[a]['total_sites']:,} |")
        L += ['']
        L += ['### What the new latents mean', '', f"Measured on {lt['graphs']} fresh graphs ({lt['rows_fit'] + lt['rows_held']:,} pair rows): {lt['fired']} of {lt['fired'] + lt['never_fired']} latents fired, {lt['named']} can be named on held-out graphs (tier A: {lt['tier_a']}), {lt['never_fired']} never fired. The full list is in `15-latent-dictionaries.md`.", '']
        named = sorted([(f, v) for f, v in lt['latents'].items() if v['tier'] != '-'], key=lambda x: -x[1]['best'][0][3])[:3]
        for f, v in named:
            b = v['best'][0]; L.append(f"- latent f{f} (tier {v['tier']}): {lt['conditions'][b[0]]['text']}; held-out precision {b[1]:.2f}, recall {b[2]:.2f}, F1 {b[3]:.2f}.")
        L += ['']
        fg = fig[a]; L += ['### The earlier Figure 4 / Figure 7 study (node-site features)', '', f"- examples: {fg['n_examples']} independently sampled graphs; downstream interventions tested: {fg['n_downstream_tests']}, confirmed: {fg['n_downstream_confirmed']} ({pct(fg['downstream_confirmed_frac'], 0)}); trivial tests set aside: {fg['n_trivial_tests']}.",
                                  f"- examples with a majority of confirmed tests: {fg['n_examples_majority_confirmed']} of {fg['n_examples_with_tests']} ({pct(fg['example_confirmed_frac'], 0)}).", f"- ground-truth harness (phase 0): {ph0[a]['l1_pass']} of {ph0[a]['l1_total']} precondition checks passed. {ph0[a]['l2_note']}.", '']
    return '\n'.join(L)

# ---------------------------------------------------------------------------------------------------------------------------------------------
# 15 latent dictionaries
# ---------------------------------------------------------------------------------------------------------------------------------------------
def latents_doc():
    L = ['# Latent dictionaries: what the edge-site latents do', '', GEN, '',
         'These tables are the measured behaviour of the latents of the edge-site transcoders, one section per algorithm. The method is in `07-data-files-and-formats.md` (file `edge_tc/<algo>.latents.json`) and `11-testing-and-verification.md`.', '',
         'How to read them:', '', '- **fires on** is the share of all pair rows (sender -> receiver pairs at one step) on which the latent is among the 8 active ones.', '- **effect** is the change of the receiver\'s main target logit per unit of the latent\'s activation, as mean +- standard deviation over all measured activations, and the share of activations where it is positive. For categorical targets the logit is that of the class the model predicts.',
         '- **real edge / non-edge / self** is the share of the latent\'s firings that happen on pairs of that kind. Compare with the share of such pairs among all pairs (shown with each algorithm).', '- **P / R / F1** are precision, recall and F1 of the best condition, scored on the held-out (odd-seed) graphs. The condition is chosen on the even-seed graphs. A latent is named only when its held-out F1 is at least 0.5 (tier B) or 0.8 (tier A).',
         '- **examples** are (seed, step, sender, receiver, activation) for the three strongest activations; the page loads them with the "show" button.', '']
    for a in ALGOS:
        lt = lat[a]; C = lt['conditions']; base = {c['id']: c['base_rate_held'] for c in C}
        L += [f'## {ALG[a][0]} (`{a}`)', '', f"- graphs: {lt['graphs']} (even seeds {lt['graphs_fit']} to choose conditions, odd seeds {lt['graphs'] - lt['graphs_fit']} to score them); pair rows {lt['rows_fit']:,} + {lt['rows_held']:,}; up to {lt['max_steps_per_graph']} evenly spaced steps per graph",
              f"- latents that fire: {lt['fired']} of {lt['fired'] + lt['never_fired']}; never fired: {lt['never_fired']}; named: {lt['named']} (tier A {lt['tier_a']})", f"- effect measured on: {lt['effect_of']} (calls: {lt['effect_calls']:,}; worst sum check {lt['max_sum_check']:.1e})",
              f"- share of pairs that are real edges / non-edges / self pairs (held-out rows): {pct(base['edge'])} / {pct(base['nonedge'])} / {pct(base['self'])}", '', '### Conditions tested', '', '| condition | meaning | share of held-out pair rows where it is true |', '|---|---|---|']
        for c in C:
            L.append(f"| `{c['id']}` | {c['text']} | {pct(c['base_rate_held'], 2)} |")
        L += ['']
        named = sorted([(int(f), v) for f, v in lt['latents'].items() if v['tier'] != '-'], key=lambda x: (-x[1]['best'][0][3], x[0]))
        L += [f'### Named latents ({len(named)})', '']
        if named:
            L += ['| latent | tier | meaning | P | R | F1 | fires on | effect mean +- sd | positive | real edge / non-edge / self | strongest activation |', '|---|---|---|---|---|---|---|---|---|---|---|']
            for f, v in named:
                b = v['best'][0]; e = v['eff']; ex = v['ex'][0] if v['ex'] else None
                L.append(f"| f{f} | {v['tier']} | {C[b[0]]['text']} | {b[1]:.2f} | {b[2]:.2f} | {b[3]:.2f} | {pct(v['rate'])} | {f'{e[0]:+.3f} +- {e[1]:.3f}' if e else '-'} | {pct(e[3], 0) if e else '-'} | {pct(v['kind'][0], 0)} / {pct(v['kind'][1], 0)} / {pct(v['kind'][2], 0)} | {f'seed {ex[0]}, step {ex[1]}, {ex[2]}->{ex[3]}, {ex[4]}' if ex else '-'} |")
            L += ['']
            L += ['Runner-up conditions for the named latents (held-out F1):', '', '| latent | second best | F1 | third best | F1 |', '|---|---|---|---|---|']
            for f, v in named:
                b2 = v['best'][1] if len(v['best']) > 1 else None; b3 = v['best'][2] if len(v['best']) > 2 else None
                L.append(f"| f{f} | {f'`{C[b2[0]]['id']}`' if b2 else '-'} | {f'{b2[3]:.2f}' if b2 else '-'} | {f'`{C[b3[0]]['id']}`' if b3 else '-'} | {f'{b3[3]:.2f}' if b3 else '-'} |")
            L += ['']
        else:
            L += ['No latent reached a held-out F1 of 0.5 for any condition.', '']
        top = sorted([(int(f), v) for f, v in lt['latents'].items()], key=lambda x: -x[1]['rate'])[:20]
        L += ['### The 20 most frequently firing latents (named or not)', '', '| latent | fires on | mean activation | max | real edge / non-edge / self | effect mean +- sd | positive | best held-out condition | F1 | named |', '|---|---|---|---|---|---|---|---|---|---|']
        for f, v in top:
            b = v['best'][0] if v['best'] else None; e = v['eff']
            L.append(f"| f{f} | {pct(v['rate'])} | {v['act']} | {v['max']} | {pct(v['kind'][0], 0)} / {pct(v['kind'][1], 0)} / {pct(v['kind'][2], 0)} | {f'{e[0]:+.3f} +- {e[1]:.3f}' if e else '-'} | {pct(e[3], 0) if e else '-'} | {f'`{C[b[0]]['id']}`' if b else '-'} | {f'{b[3]:.2f}' if b else '-'} | {v['tier'] if v['tier'] != '-' else 'no'} |")
        L += ['']
        eff = sorted([(int(f), v) for f, v in lt['latents'].items() if v['eff'] and v['eff'][2] >= 200], key=lambda x: -abs(x[1]['eff'][0]))[:12]
        L += ['### The 12 latents with the strongest average effect (at least 200 measured activations)', '', '| latent | effect mean +- sd | positive | measured activations | fires on | named | best held-out condition (F1) |', '|---|---|---|---|---|---|---|']
        for f, v in eff:
            b = v['best'][0] if v['best'] else None; e = v['eff']
            L.append(f"| f{f} | {e[0]:+.3f} +- {e[1]:.3f} | {pct(e[3], 0)} | {e[2]:,} | {pct(v['rate'])} | {v['tier'] if v['tier'] != '-' else 'no'} | {f'`{C[b[0]]['id']}` ({b[3]:.2f})' if b else '-'} |")
        L += ['']
        kinds = [0, 0, 0];
        for v in lt['latents'].values():
            k = max(range(3), key=lambda i: v['kind'][i]); kinds[k] += 1
        L += ['### Where the latents fire (all latents that fire)', '', f"- latents whose firings are mostly on real edges: {kinds[0]}; mostly on non-edges: {kinds[1]}; mostly on self pairs: {kinds[2]}.",
              f"- latents with a one-sided effect (positive in at least 90% or at most 10% of activations): {sum(1 for v in lt['latents'].values() if v['eff'] and (v['eff'][3] >= 0.9 or v['eff'][3] <= 0.1))} of {sum(1 for v in lt['latents'].values() if v['eff'])} with a measured effect.", '']
    return '\n'.join(L)

# ---------------------------------------------------------------------------------------------------------------------------------------------
# 16 training reports
# ---------------------------------------------------------------------------------------------------------------------------------------------
def reports_doc():
    L = ['# Edge-site transcoder training reports', '', GEN, '', 'One section per algorithm, copied field by field from `clrs-transcoder-out/<algo>/report.json` (the output of the training notebook `clrs-transcoder.ipynb`). The meaning of each block is explained in `07-data-files-and-formats.md`.', '',
         'Conventions: NMSE = FVU = sum of squared reconstruction errors divided by the variance of the true message; "off" = the unmodified network; "plain" = the transcoder wired in without the error node; "plumb" = reconstruction plus error node (must equal "off"); "full" = reconstruction everywhere with winners and hints recomputed; "node_full" / "both_full" = the node-site transcoder replaced alone / together with the edge site.', '']
    for a in ALGOS:
        r = rep[a]; c = r['config']; e1 = r['E1']; e2 = r['E2']; d = r['direct']
        L += [f'## {ALG[a][0]} (`{a}`)', '', f"- tier {r['tier']}; baseline MPNN score val {r['baseline']['val']:.4f}, test {r['baseline']['test']:.4f}", f"- configuration: activation `{c['act']}`, D = {c['D']}, k = {c['k']}, {c['steps']:,} steps; node site: {c.get('node_site')}, D_node = {c.get('D_node')}, k_node = {c.get('k_node')}, {c.get('node_steps'):,} steps",
              f"- rows: train {r['rows']['train']:,}, validation {r['rows']['val']:,}, test (64 nodes) {r['rows']['test_n64']:,}" + (f"; node site rows: train {r['rows_node']['train']:,}, validation {r['rows_node']['val']:,}, test {r['rows_node']['test_n64']:,}" if 'rows_node' in r else ''),
              f"- training time: edge site {r['train_seconds']:.0f} s, node site {r.get('train_seconds_node', 0):.0f} s, whole run {r['minutes']} min", f"- hint policy for rows: {r['hint_policy']['rows']}", f"- parity with the recorded score: reproduced {r['parity']['test_f1_reproduced']}, recorded {r['parity']['test_f1_recorded']}, difference {r['parity']['abs_diff']}",
              f"- offline parity (recomputed site input s, output y, hidden state h, absolute): {r['offline_parity']['s']:.2e}, {r['offline_parity']['y']:.2e}, {r['offline_parity']['h']:.2e}; relative: {r['offline_parity_rel']['s']:.2e}, {r['offline_parity_rel']['y']:.2e}, {r['offline_parity_rel']['h']:.2e}", '']
        L += ['### E1: reconstruction of the message (edge site)', '', '| split | NMSE | active latents per row | dead fraction | rows |', '|---|---|---|---|---|']
        for sp in ['train', 'val', 'test_n64']:
            if sp in e1:
                L.append(f"| {sp} | {e1[sp]['nmse']:.5f} | {e1[sp]['l0']:.2f} | {e1[sp]['dead_frac']:.3f} | {e1[sp]['rows']:,} |")
        L += ['', 'NMSE per algorithm step:', '', '| split | ' + ' | '.join(f'step {k}' for k in sorted(e1['val']['nmse_per_step'], key=int)) + ' |', '|---|' + '---|' * len(e1['val']['nmse_per_step'])]
        for sp in ['train', 'val', 'test_n64']:
            if sp in e1:
                ks = sorted(e1[sp]['nmse_per_step'], key=int); L.append(f"| {sp} | " + ' | '.join(f"{e1[sp]['nmse_per_step'][k]:.5f}" for k in ks) + ' |')
        L += ['']
        if 'E1_node' in r:
            en = r['E1_node']; L += ['### E1 for the node site (not used on the site)', '', '| split | NMSE | active latents per row | dead fraction | rows |', '|---|---|---|---|---|']
            for sp in ['train', 'val', 'test_n64']:
                if sp in en:
                    L.append(f"| {sp} | {en[sp]['nmse']:.5f} | {en[sp]['l0']:.2f} | {en[sp]['dead_frac']:.3f} | {en[sp]['rows']:,} |")
            L += ['']
        L += ['### Direct and frozen one-step replacement', '', f"- winner flips: {d['winner_flips']['n_flips']:,} of {d['winner_flips']['n_channels']:,} channels ({pct(d['winner_flips']['flip_rate'])}); channels at risk (2 x error >= gap): {d['winner_flips']['n_at_risk']:,}; violations of the bound: {d['winner_flips']['n_violations']}", '',
              'Relative error of the next hidden state, per step:', '', '| mode | ' + ' | '.join(f'step {k}' for k in sorted(d['hidden_rel_error']['direct'], key=int)) + ' |', '|---|' + '---|' * len(d['hidden_rel_error']['direct'])]
        for mode in ['direct', 'frozen']:
            ks = sorted(d['hidden_rel_error'][mode], key=int); L.append(f"| {mode} | " + ' | '.join(f"{d['hidden_rel_error'][mode][k]:.4f}" for k in ks) + ' |')
        L += ['', '### E2: the transcoder inside the network', '', '| split | off | plain | plumb | full | node_full | both_full | retention full | retention node | retention both | plumb diff | plain diff |', '|---|---|---|---|---|---|---|---|---|---|---|---|']
        for sp in ['val', 'test']:
            if sp in e2:
                o = e2[sp]; L.append(f"| {sp} | {o['off']['score']:.4f} | {o['plain']['score']:.4f} | {o['plumb']['score']:.4f} | {o['full']['score']:.4f} | {o['node_full']['score']:.4f} | {o['both_full']['score']:.4f} | {o['retention_full']:.4f} | {o['retention_node_full']:.4f} | {o['retention_both_full']:.4f} | {o['plumb_abs_diff']:.1e} | {o['plain_abs_diff']:.1e} |")
        L += ['', '### Training history of the edge-site transcoder', '', '| step | batch NMSE | auxiliary loss | active latents | dead latents now | seconds |', '|---|---|---|---|---|---|']
        for h in r['train_history']:
            L.append(f"| {h['step']:,} | {h['nmse_batch']:.5f} | {h['aux']:.5f} | {h['l0']:.2f} | {h['dead_now']} | {h['sec']} |")
        L += ['']
    return '\n'.join(L)

