def fig47_doc():
    ff = J(R, 'fig47', 'final_finding.json'); p3 = J(R, 'fig47', 'phase3_summary.json'); p1 = J(R, 'fig47', 'phase1_summary.json')
    L = ['# The earlier Figure 4 / Figure 7 study (`fig47/`)', '', GEN, '',
         'Before the edge-site transcoders, the project reproduced the two central figures of the Anthropic circuit-tracing paper for all twelve algorithms using the node-site transcoder (192 features, 8 active). This document explains what each result file in `fig47/` contains and tabulates the numbers.', '',
         '## The two figures', '', '- **Figure 4 (one example):** pick one real graph and one real prediction; group the features into a few named supernodes; show the supernodes feeding the prediction; then clamp one supernode (to -2 times its value) and show what the real network does.',
         '- **Figure 7 (validation sweep):** repeat the clamp over many examples and many supernodes to see whether the story of one example survives. Here: 15 independently sampled graphs per algorithm.', '',
         '## Result files', '', '| file pattern | what it holds |', '|---|---|', '| `phase0_results.json` | the three-layer ground-truth harness: precondition checks (layer 1), stage correctness (layer 2) and invariants (layer 3) per algorithm |', '| `phase1_summary.json`, `phase1.py` | supernode distillation and frozen predictions for the pilot algorithm (bfs) |',
         '| `phase2_<algo>.json`, `phase2_summary.json` | single-example intervention panels: supernode, predicted and actual direction, verdict (CONFIRMED / NOT_CONFIRMED / TRIVIAL), clamp step, factor, base and new logit |', '| `phase2agg_<algo>.json`, `phase2agg_summary.json` | the 15-example sweep per algorithm (Figure 7) |',
         '| `phase2_6_*` | diagnostics for the finding that accuracy does not predict how confirmable the circuits are |', '| `phase3_*` | whether clamping that changes the top-k mask is confirmed more or less often, and the recurring-feature analysis |', '| `fig4_baseline_<algo>.json`, `fig4_viewer_data.json` | the data behind the Figure 4 pages |',
         '| `single_example_<algo>.json`, `predictions_<algo>.json` | one example per algorithm and the model predictions used by the viewers |', '| `fig4_<algo>.png`, `fig7_<algo>.png`, `fig4.png`, `fig7.png` | the rendered figures |', '| `viewer_fig47.html` | the interactive page served on port 8080 of the instance |', '| `final_finding.json` | the reconciled verdict on the recurring-feature question |', '',
         '## Figure 7 sweep: how many downstream interventions were confirmed', '', '| algorithm | class | examples | downstream tests | confirmed | confirmed fraction | trivial tests set aside | examples with a confirmed majority |', '|---|---|---|---|---|---|---|---|']
    for a in ALGOS:
        g = fig[a]; s = SUM[a]; gap = s['best_val_f1'] - s['test_f1']
        L.append(f"| `{a}` | {'CLEAN' if gap < 0.10 else 'SEVERE'} | {g['n_examples']} | {g['n_downstream_tests']} | {g['n_downstream_confirmed']} | {pct(g['downstream_confirmed_frac'], 0)} | {g['n_trivial_tests']} | {g['n_examples_majority_confirmed']} of {g['n_examples_with_tests']} |")
    have = [a for a in ALGOS if fig[a]['downstream_confirmed_frac'] is not None]; clean = [fig[a]['downstream_confirmed_frac'] for a in have if SUM[a]['best_val_f1'] - SUM[a]['test_f1'] < 0.10]; sev = [fig[a]['downstream_confirmed_frac'] for a in have if SUM[a]['best_val_f1'] - SUM[a]['test_f1'] >= 0.10]
    lo = min(have, key=lambda a: fig[a]['downstream_confirmed_frac']); hi = max(have, key=lambda a: fig[a]['downstream_confirmed_frac']); best_acc = max(have, key=lambda a: SUM[a]['test_f1'])
    L += ['', f"Algorithms with at least one downstream test: {len(have)} of 12. Mean confirmed fraction: CLEAN algorithms {pct(sum(clean) / len(clean))} (n = {len(clean)}), SEVERE algorithms {pct(sum(sev) / len(sev)) if sev else 'n/a'} (n = {len(sev)}). The lowest confirmed fraction is `{lo}` ({pct(fig[lo]['downstream_confirmed_frac'], 0)}), the highest `{hi}` ({pct(fig[hi]['downstream_confirmed_frac'], 0)}); the most accurate model on 64-node graphs is `{best_acc}` ({pct(SUM[best_acc]['test_f1'])}) with {pct(fig[best_acc]['downstream_confirmed_frac'], 0)} confirmed. The project README summarises this as: accuracy on bigger graphs does not predict how well the circuits are confirmed by intervention.", '',
          '## Does clamping that changes the top-k set behave differently? (phase 3)', '', 'For every downstream test, whether the clamp changed which features are in the top-k set ("mask changed") and whether the test was confirmed.', '', '| algorithm | confirmed, mask changed | confirmed, mask same | not confirmed, mask changed | not confirmed, mask same | tests |', '|---|---|---|---|---|---|']
    for a in ALGOS:
        t = mch[a]['table']; L.append(f"| `{a}` | {t['CONFIRMED_maskchg']} | {t['CONFIRMED_same']} | {t['NOT_CONFIRMED_maskchg']} | {t['NOT_CONFIRMED_same']} | {mch[a]['n']} |")
    L += ['', '## The ground-truth harness (phase 0)', '', '| algorithm | layer-1 checks passed | note on layer 2 | layer-3 invariant results |', '|---|---|---|---|']
    for a in ALGOS:
        L.append(f"| `{a}` | {ph0[a]['l1_pass']} of {ph0[a]['l1_total']} | {ph0[a]['l2_note']} | {sum(1 for x in ph0[a]['l3_results'] if x is True)} true, {sum(1 for x in ph0[a]['l3_results'] if x is False)} false, {sum(1 for x in ph0[a]['l3_results'] if x is None)} not applicable |")
    L += ['', '## The recurring-feature question', '', f"Verdict: **{ff['verdict']}** ({ff['n_algos_confirming']} of {ff['n_algos_tested']} algorithms confirm). Confirming: {', '.join(ff['confirming_algos'])}. Not confirming: {', '.join(ff['non_confirming_algos'])}.", '', textwrap.fill(ff['callout_text'], 160), '',
          '## Per-algorithm mean label F1 and confirmation (phase 3 summary)', '', '| algorithm | mean F1 of the labelled features | confirmed | total | fraction | class |', '|---|---|---|---|---|---|']
    for row in p3:
        L.append(f"| `{row['algo']}` | {'n/a' if row['mean_f1'] is None else format(row['mean_f1'], '.3f')} | {row['confirmed']} | {row['total']} | {pct(row['frac'], 0)} | {row['class']} |")
    L += ['', '## The pilot supernode distillation (phase 1, bfs)', '', f"- target: `{p1['bfs']['target']}`, baseline logit {p1['bfs']['baseline_logit']:.3f}, explained at step {p1['bfs']['step']}, node {p1['bfs']['node']}, source {p1['bfs']['source']}", f"- edges between graph nodes: {p1['bfs']['n_edges_all']}; edges between supernodes: {p1['bfs']['n_edges_supernode']}",
          '', 'Supernode edges into the target:', '', '| supernode | weight |', '|---|---|']
    for k, v in p1['bfs']['supernode_edges_into_target']:
        L.append(f"| {k} | {v} |")
    L += ['', 'Mean label F1 per supernode:', '', '| supernode | mean F1 |', '|---|---|'] + [f'| {k} | {v:.3f} |' for k, v in p1['bfs']['mean_f1_per_supernode'].items()] + ['']
    return '\n'.join(L)

