# 06b hover-text catalog
# ---------------------------------------------------------------------------------------------------------------------------------------------
def tips_doc():
    L = ['# Hover-text catalog: every explanation the page can show', '', GEN, '',
         'The page explains its own vocabulary in hover cards (`explain.js`). Each card has up to four parts: **what it is**, **why it is there**, and **how to read it / a technical note**. The shared table `GL` is used by both pages; the table `GL_EDGE` overrides entries on the main page (edge-site transcoders) and is ignored on `/demo`.', '',
         'Besides these fixed entries the page builds dynamic cards for graph nodes (`node:`), table cells (`cell:`), attribution nodes and edges (`an:`, `ae:`), feature labels (`fl:`) and dynamic values (`dyn:`).', '', f"- shared entries (`GL`): {len(tips['GL'])}", f"- edge-site overrides (`GL_EDGE`): {len(tips['GL_EDGE'])}", '']
    def dump(title, d):
        out = [f'## {title}', '']
        for k in sorted(d):
            e = d[k]; out += [f'### `{k}`: {e[0]}', '']
            for lab, txt in zip(['What it is', 'Why it is there', 'Technical note', 'Extra'], e[1:]):
                if txt:
                    out += [f'- **{lab}:** {txt}']
            out += ['']
        return out
    L += dump('Shared entries (used on `/demo`, and on the main page where not overridden)', tips['GL']); L += dump('Entries that differ on the main page (edge-site transcoders)', tips['GL_EDGE'])
    return '\n'.join(L)


