def describe(path):
    for rx, role, d in RULES:
        if re.search(rx, path): return role, d
    return 'other', '(no description yet)'

def filemap_doc():
    import subprocess
    files = subprocess.run(['git', '-C', R, 'ls-files'], capture_output=True, text=True, check=True).stdout.split('\n')
    files = sorted(f for f in files if f)
    ign = [l.strip() for l in open(os.path.join(R, '.dockerignore')) if l.strip() and not l.startswith('#')]
    def in_image(f):
        return not any(f == i or f.startswith(i.rstrip('/') + '/') for i in ign if not i.startswith('*')) and not f.endswith(('.pyc', '.log'))
    L = ['# Repository file map: which file means what', '', GEN, '', f'The repository has {len(files)} tracked files (listed by `git ls-files`). This document describes every one of them. Roles: **runtime** (used when the site runs), **build** (used to build the image or the data), **analysis** (scripts and results of the research), **test** (checks), **docs**, **ci** (GitHub Actions).', '',
         'The column "in image" says whether the file is copied into the Docker image (everything except what `.dockerignore` excludes). Model bundles (`models/`) and the Python caches are created inside the image and are not tracked.', '', '## How the pieces fit together', '', '```text',
         'browser                     server (port 8766, server_128.py)                 data on disk',
         '-------                     ---------------------------------                 ------------',
         'viewer3.html  <---------    GET /            (page with build id filled in)   viewer3.html',
         'explain.js, attrview.js,    GET /<script>?v=BUILD  (gzip, immutable cache)    *.js',
         'mpnn.js, attrib.js,',
         'clrs-edge-attrib.js,',
         'mpnn_worker.js',
         'Web Worker  <-----------    GET /models/<algo>.json|bin?v=BUILD               models/ (made at image build by model_export.py from checkpoints_v3/)',
         '                            GET /edge_tc/<algo>.bin|json|latents.json         edge_tc/ (made by clrs_export_edge_tc.py + clrs_edge_latents.js)',
         '                            GET /api/instance?algo&n&p&seed&v=BUILD           CLRS sampler (jax-free path through model_export.build_instance)',
         '                            GET /api/weights, /api/feature_labels (demo)      algos/<algo>/*',
         '                            GET /api/contexts (demo)                          runs the JAX model: top-activating examples',
         '                            GET /api/graph (fallback)                         runs the JAX model for one graph',
         'port 8080 (8767 in the container): fig47/static_server.py                     fig47/ (plain files)', '```', '',
         '## Top-level files and folders', '', '| path | what it is |', '|---|---|',
         '| `viewer3.html`, `demo.html` | the two pages |', '| `*.js` in the root | the scripts the pages load |', '| `server_128.py`, `start.sh`, `config.py` | the server, its entry point and its configuration |', '| `model_export.py`, `capture_net.py`, `pipeline.py` | model export, network wrapper, analysis pipeline |',
         '| `clrs_export_edge_tc.py` | converter for the edge-site transcoders |', '| `algos/` | node-site transcoders, labels and facts per algorithm (36 files) |', '| `edge_tc/` | edge-site transcoders, their latent tables and the quality summary (37 files) |', '| `checkpoints_v3/` | the trained MPNNs (Git LFS) and one example of step pictures |',
         '| `fig47/` | the earlier Figure 4 / Figure 7 study: scripts, results, figures, viewer, static server (138 files) |', '| `verification/` | all tests |', '| `tools/` | helpers for checks and for generating these documents |', '| `.github/workflows/` | the twelve GitHub Actions workflows |', '| `docs/` | this documentation |', '| `Dockerfile`, `.dockerignore`, `requirements.txt` | image build |', '', '## Every tracked file', '', '| path | size | role | in image | description |', '|---|---|---|---|---|']
    sizes = {}
    for f in files:
        try: sizes[f] = os.path.getsize(os.path.join(R, f))
        except OSError: sizes[f] = 0
    for f in files:
        role, d = describe(f); L.append(f"| `{f}` | {hs(sizes[f])} | {role} | {'yes' if in_image(f) else 'no'} | {d} |")
    L += ['', '## Totals by folder', '', '| folder | files | bytes |', '|---|---|---|']
    agg = {}
    for f in files:
        k = f.split('/')[0] if '/' in f else '(root)'; a = agg.setdefault(k, [0, 0]); a[0] += 1; a[1] += sizes[f]
    for k, (n, b) in sorted(agg.items(), key=lambda x: -x[1][1]):
        L.append(f'| `{k}` | {n} | {hs(b)} |')
    L += ['', f'Files without a description rule: {sum(1 for f in files if describe(f)[0] == "other")}.', '']
    return '\n'.join(L)

for name, fn in [('04-the-12-algorithms.md', algos_doc), ('15-latent-dictionaries.md', latents_doc), ('16-transcoder-training-reports.md', reports_doc), ('17-fig47-study-results.md', fig47_doc), ('06b-hover-text-catalog.md', tips_doc), ('03-repository-file-map.md', filemap_doc)]:
    text = fn(); open(os.path.join(DOCS, name), 'w').write(text + '\n'); print(f'{name:45s} {text.count(chr(10)) + 1:6d} lines')
